 const selected=side=>Number(state[`${side}Ocpd`])===0?'not selected':state[`${side}Ocpd`]+' A';
 return core+section('ocpd','Optional: selected breakers',ocpd,ocpd?`Primary ${selected('primary')} / Secondary ${selected('secondary')}${conductors?' · required for conductor checks':''}`:'')+section('conductors','Optional: load & secondary conductors',conductors,conductors?`${state.secondaryRule} / ${state.lengthFt} ft`:'');
