function rowsHTML(state){return `<p class="conduit-heading">Conductors in this raceway</p>${state.rows.map((r,i)=>`<div class="conduit-row"><div class="field"><label for="row-size-${i}">Conductor ${i+1}</label><select id="row-size-${i}" data-row="${i}" data-key="size">${sizes().map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(r.size)?'selected':''}>${esc(t)} · THHN</option>`).join('')}</select></div><div class="field"><label for="row-count-${i}">Count</label><input id="row-count-${i}" data-row="${i}" data-key="count" type="number" min="1" max="1000" step="1" value="${esc(r.count)}" required></div><button class="button" type="button" data-remove="${i}" aria-label="Remove conductor group ${i+1}" ${state.rows.length===1?'disabled':''}>×</button></div>`).join('')}<button class="button add-row" id="add-row" type="button">+ Add conductor group</button>`}
function calculator(id){const m=modules.find(m=>m.id===id);if(!m){overview();return}active=id;nav();document.title=`${m.title} · MEP Workbench`;document.querySelector('#main').innerHTML=`<div class="page-header"><div><h1>${m.title}</h1></div><div class="actions"><button class="button" id="reset">Reset</button><button class="button" id="print">Print</button><button class="button" id="copy-summary" disabled>Copy summary</button><button class="button" id="export-pdf" disabled>PDF report</button><button class="button" id="save-calculation" disabled>Save calculation</button></div></div><p id="action-status" class="action-status" role="status"></p><p id="storage-status" class="warning storage-status" role="status"></p><div class="calculator-layout"><section class="panel" aria-label="Calculation inputs">${['conductor','protection'].includes(id)&&states[id].migrationNotice?`<div class="warning" role="status">${esc(states[id].migrationNotice)}</div>`:''}<form id="calculator-form" novalidate><div class="form-fields">${id==='protection'?protectionFieldsHTML(m,states[id]):m.fields.map(f=>fieldHTML(f,states[id])).join('')}${id==='conduit'?rowsHTML(states[id]):''}</div></form>${guidanceHTML(m,states[id])}</section><section id="results" class="results-column" aria-label="Calculation results" aria-live="polite" aria-atomic="true"></section></div><details class="panel info-panel" data-print-details><summary>Scope & references</summary><div class="info-content"><ul>${m.limitations.map(l=>`<li>${l}</li>`).join('')}</ul><h3>Source references</h3><div id="sources"></div></div></details>${note()}`;
const form=document.querySelector('#calculator-form');const handleInput=event=>{const el=event.target;if(!el.matches('input,select'))return; if(event.type==='input'&&(el.tagName==='SELECT'||el.type==='radio'))return;if(id==='protection'&&el.name.endsWith('Preset')){const key=el.name.replace('Preset','');states[id][`${key}Mode`]=el.value==='custom'?'custom':'standard';states[id][`${key}System`]='auto';if(el.value!=='custom')states[id][key]=Number(el.value);states[id][`${key}Confirmed`]=false;states[id].primaryOcpd=0;states[id].secondaryOcpd=0;states[id].installationConfirmed=false;save();calculator(id);return;}if(el.dataset.row!==undefined){states[id].rows[+el.dataset.row][el.dataset.key]=el.dataset.key==='count'?(el.value===''?'':Number(el.value)):el.value}else{const f=m.fields.find(f=>f.key===el.name);states[id][el.name]=['number','voltage','protection-voltage'].includes(f?.type)?(el.value===''?'':Number(el.value)):el.value;if(['clamps','voltageDropEnabled','installationConfirmed','ocpdCheckEnabled','conductorCheckEnabled'].includes(el.name))states[id][el.name]=el.value==='true'}if(id==='protection'){if(['breakerSide','kva','phase','primary','secondary','protection'].includes(el.name)){states[id].primaryOcpd=0;states[id].secondaryOcpd=0;}}if(id==='protection'&&el.name==='conductorCheckEnabled'&&enabled(states[id].conductorCheckEnabled))states[id].ocpdCheckEnabled=true;if(id==='protection'&&el.name==='ocpdCheckEnabled'&&enabled(states[id].conductorCheckEnabled))states[id].ocpdCheckEnabled=true;if(['conductor','service','protection'].includes(id)&&el.name==='ambient'){states[id].ambientBasis=typeof event.detail?.ambientBasis==='string'?event.detail.ambientBasis:'';const basis=document.querySelector('#ambient-basis');if(basis)basis.textContent=states[id].ambientBasis}if(['conductor','service','protection'].includes(id)&&['terminal','material'].includes(el.name))states[id].terminal90Confirmed=false;const voltageField=m.fields.find(f=>['voltage','protection-voltage'].includes(f.type)&&(f.key===el.name||f.phaseKey===el.name||`${f.key}Mode`===el.name||`${f.key}System`===el.name));if(voltageField){for(const f of m.fields.filter(f=>['voltage','protection-voltage'].includes(f.type)&&(f===voltageField||f.phaseKey===el.name))){states[id][`${f.key}Confirmed`]=false;const acknowledgement=form.querySelector(`[name="${f.key}Confirmed"]`);if(acknowledgement)acknowledgement.value='false'}}if(id==='protection'&&['phase','configuration','secondaryRule','lengthFt','protection'].includes(el.name)){states[id].installationConfirmed=false;const acknowledgement=form.querySelector('[name="installationConfirmed"]');if(acknowledgement)acknowledgement.value='false'}save();if((['conductor','service','protection'].includes(id)&&['terminal','material'].includes(el.name))||['mode','voltageDropEnabled','protection','secondaryRule','ocpdCheckEnabled','conductorCheckEnabled','breakerSide','primaryOcpd','secondaryOcpd'].includes(el.name)||(id==='protection'&&['kva','primary','secondary'].includes(el.name)&&event.type==='change')||(voltageField&&voltageField.key!==el.name)||el.name?.endsWith('Confirmed')){calculator(id);if(id==='protection'&&['protection','breakerSide'].includes(el.name))document.querySelector(`input[name="${el.name}"]:checked`)?.focus();return}calculate(m)};form.addEventListener('input',handleInput);form.addEventListener('change',handleInput);if(['conductor','service','protection'].includes(id))attachAmbientHelper(form);
form.addEventListener('submit',e=>e.preventDefault());document.querySelector('#reset').onclick=()=>{states[id]=defaults(m);delete calculationNames[id];save();calculator(id)};document.querySelector('#print').onclick=()=>window.print();bindReportActions();showStorageWarning();if(id==='conduit'){document.querySelector('#add-row').onclick=()=>{states[id].rows.push({size:'12',count:1});save();calculator(id)};document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{states[id].rows.splice(+b.dataset.remove,1);save();calculator(id)})}calculate(m)}
// Keep context-specific warnings visible; move only known standing notes into details.
const standingNote=/^(NEC 2023 baseline:|The selected OCPD must|Enter the final design load,|Circuit configuration determines|One complete identical set|EMT fill uses|General feeders\/branches|Cu EGC is|Minimum EMT is|Customer-owned general commercial|Provide a completed service load|Review NEC 230|Service grounding and bonding|Any neutral is assumed|Each complete set occupies|Parallel ungrounded and neutral|Maximum modeled total service|Use line-to-line voltage for three-phase|Ideal nameplate full-load|Use true power factor for the load|Balanced three-phase load;|Electrical input watts only|NEC Chapter 9 Tables|No cables, bare grounds|Approximate resistance-only|Typical 3% branch|A voltage-drop size|NEC 2023 314|Each standard device yoke|Mixed sizes, long unbroken)/;
// Only known routine transformer information is collapsed. Unknown and conditional
// warnings remain visible; the calculation output is untouched for saves/reports.
const protectionStandingNote=/^(Maximum modeled permitted OCPDs are table limits|NEC 2023 baseline,|Only ordinary dry-type transformers|The design load is preadjusted|OCPDs are table-based candidates only|Phase conductors only\.|Use the lowest verified temperature rating|No NEC 240\.4\(B\)|[0-9]+ CCC per raceway are derived)/;
const protectionMetricLabels=[
 ['Maximum modeled permitted primary OCPD','Maximum modeled primary OCPD'],
 ['Maximum modeled permitted secondary OCPD','Maximum modeled secondary transformer OCPD'],
 ['Primary full-load current'],['Secondary full-load current']
];
function protectionPresentation(results){
 const prominent=protectionMetricLabels.map(labels=>results.find(r=>labels.includes(r.label))).filter(Boolean);
 return {prominent,secondary:results.filter(r=>!prominent.includes(r))};
}
const scopeNotes={
 protection:'Maximum modeled permitted OCPDs are winding-protection limits, not recommended breakers. Selected-device and secondary conductor checks are optional and separate. Grounding, bonding, inrush, fault current, voltage drop and conduit sizing are outside this module.',
 conductor:'General feeders/branches, THHN/THWN-2 only; no specialized circuits. One set per EMT. Full-size neutral assumed; Cu EGC includes the modeled proportional increase when voltage-drop sizing is enabled. Review neutral and grounding details separately; the optional voltage-drop estimate has its own limits. Final 2023 fill dimensions not independently verified.',
 service:'Customer-owned commercial service phase conductors to a single main disconnect only. Neutral, grounding, bonding and conduit are not sized. Use a completed service load calculation; no dwelling reduction.',
 transformer:'Nameplate currents only. Protection, inrush, secondary conductor sizing and bonding require separate checks.',
 power:'Use true power factor. VA equals watts only at PF = 1.',
 amps:'Steady-state electrical input power; balanced three-phase, line-to-line voltage. No circuit sizing or mechanical-efficiency adjustment.',
 conduit:'THHN/THWN-2 in EMT only; count every conductor. Fill does not verify ampacity or pulling feasibility. Final 2023 dimensions not independently verified.',
 drop:'One segment only. NEC generally recommends 3% branch / 5% feeder + branch; applicable 2021 IECC C405.10 limits the full customer-owned service + feeder + branch path to 5%. This result does not establish combined-path compliance.',
 box:'Uniform conductor size only. Use marked usable volume; mixed sizes and special fittings require separate review.'
};
const primaryMetrics={conductor:['Total OCPD','Minimum EMT per set','Separate EMT raceways','Combined usable ampacity','Base-minimum Cu EGC per raceway','Modeled Cu EGC per raceway','Estimated voltage drop','Estimated drop','Target check','Voltage-drop current','Sizing basis'],service:['Total service OCPD','Combined phase ampacity','Separate conductor sets','Estimated voltage drop','Estimated drop','Target check','Voltage-drop current','Sizing basis'],conduit:['Actual fill','Permitted fill','Fill check','Minimum EMT'],drop:['Estimated voltage drop','Estimated voltage at end of run'],box:['Available box volume','Volume check']};
const metricHTML=items=>`<div class="metric-grid">${items.map(r=>`<div class="metric"><div class="metric-label">${esc(r.label)}</div><div class="metric-value">${r.displayValue!==undefined?esc(r.displayValue):formatted(r.value)}${r.unit?` <span class="metric-unit">${esc(r.unit)}</span>`:''}</div></div>`).join('')}</div>`;
let printDetails=[];
function preparePrint(){if(printDetails.length)return;printDetails=[...document.querySelectorAll('details[data-print-details]')].map(el=>({el,open:el.open}));for(const {el} of printDetails)el.open=true}
