function calculate(m){actionStatus('');currentSnapshot=null;setExportReady(false);const target=document.querySelector('#results');const inputs=[...document.querySelectorAll('#calculator-form input:not([data-ambient-helper])')];let invalid=false;for(const el of inputs){if(el.type==='radio')continue;const valid=el.checkValidity()&&el.value!=='';el.setAttribute('aria-invalid',String(!valid));invalid||=!valid}if(invalid){if(m.id==='protection')openProtectionErrors();target.innerHTML='<div class="warning error" role="alert">Check your inputs. Enter a value in each field, use nonnegative counts and loads, and keep values within the stated limits.</div>';return}let output;try{output=(m.id==='protection'?evaluateTransformerProtection:calc[m.id])(states[m.id])}catch(e){target.innerHTML='<div class="warning error" role="alert">This combination could not be calculated. Check the inputs and selected conductor sizes.</div>';console.error(e);return}if(output.error){if(m.id==='protection')openProtectionErrors();target.innerHTML=`<div class="warning error" role="alert">${esc(output.error)}</div>`;renderSources(output);return}if(['conductor','service'].includes(m.id)&&states[m.id].ambientBasis)output.steps.unshift(`Ambient design basis: ${states[m.id].ambientBasis}`);let displayResults=[...(output.results||[])];if((m.id==='power'&&states[m.id].mode==='wattsToVA')||(m.id==='amps'&&states[m.id].mode==='ampsToWatts'))[displayResults[0],displayResults[1]]=[displayResults[1],displayResults[0]];let [first,...rest]=displayResults;const keys=primaryMetrics[m.id];let prominent=keys?rest.filter(r=>keys.includes(r.label)&&!(r.label==='Base-minimum Cu EGC per raceway'&&output.results.some(x=>x.label==='Modeled Cu EGC per raceway'))):rest;let secondary=keys?rest.filter(r=>!prominent.includes(r)):[];if(m.id==='protection'){first=null;({prominent,secondary}=protectionPresentation(displayResults))}const isStanding=w=>(m.id==='drop'&&/^(AC estimate assumes|NEC general-circuit|2021 IECC|Voltage drop does not)/.test(w))||(standingNote.test(w)&&!(w.startsWith('Parallel ungrounded')&&Number(states[m.id].parallelSets)>1))||(m.id==='protection'&&(protectionStandingNote.test(w)||(w.startsWith('NEC 450.3(B) protects the transformer;')&&states.protection.protection!=='primary-only')));const visibleWarnings=(output.warnings||[]).filter(w=>!isStanding(w));const detailedNotes=(output.warnings||[]).filter(isStanding);target.innerHTML=`${first?`<div class="result-hero${m.id==='drop'?` drop-${first.status}`:''}"><div class="result-kicker">${esc(first.label)}</div><div class="result-value">${first.displayValue!==undefined?esc(first.displayValue):formatted(first.value)}${first.unit?`<span class="result-unit">${esc(first.unit)}</span>`:''}</div><div class="result-caption">${m.id==='service'?'Ungrounded phase conductor per set. Neutral, grounding and bonding require separate design.':m.id==='conductor'?'Each phase / full-size neutral conductor, in every set.':m.id==='conduit'?'Raceway fill only; verify derating separately.':m.id==='drop'?`${output.results.find(r=>r.label==='Voltage-drop guidance')?.value||''} · single-segment estimate`:m.id==='box'?'Required usable box volume.':''}</div></div>`:''}${prominent.length?metricHTML(prominent):''}<p class="scope-note">${esc(m.id==='protection'?'Modeled winding-protection limits; not recommended breakers.':scopeNotes[m.id])}</p>${m.id==='protection'&&output.results.some(r=>r.label==='Breaker pair status')?`<p class="scope-note" role="status">${output.results.filter(r=>/^Selected (primary|secondary) OCPD$/.test(r.label)).map(r=>`${esc(r.label.replace('Selected ','').replace(' OCPD',''))} ${esc(r.value)} A`).join(' / ')}${output.results.some(r=>/^Selected (primary|secondary) OCPD$/.test(r.label))?' · ':''}${esc(output.results.find(r=>r.label==='Breaker pair status').value)}. Table 450.3(B) only; below-FLC ratings may limit capacity. Verify load, inrush and installation separately.</p>`:''}${visibleWarnings.map(w=>`<div class="warning" role="status">${esc(w)}</div>`).join('')}${secondary.length||output.steps?.length||detailedNotes.length?`<details class="panel calculation-details" data-print-details><summary>Calculation details${secondary.length?' & additional results':''}</summary><div class="detail-content">${m.id==='protection'?`<p class="scope-note">${esc(scopeNotes[m.id])}</p>`:''}${secondary.length?metricHTML(secondary):''}${output.steps?.length?`<div class="breakdown"><h3>Method</h3>${output.steps.map((s,i)=>`<div class="breakdown-row"><span>${String(i+1).padStart(2,'0')}</span><span>${esc(s)}</span></div>`).join('')}</div>`:''}${detailedNotes.length?`<div class="detail-notes"><h3>Assumptions & checks</h3><ul>${detailedNotes.map(w=>`<li>${esc(w)}</li>`).join('')}</ul></div>`:''}</div></details>`:''}`;try{currentSnapshot=makeSnapshot(m,states[m.id],output);setExportReady(true)}catch(error){actionStatus(`Saving and export are unavailable: ${error.message}`)};renderSources(output)}
