function savedLibrary(){
 active='saved';currentSnapshot=null;nav();document.title='Saved calculations · MEP Workbench';let records=[],failure='';try{records=createRecordStore().list({includeTrashed:true})}catch(error){failure=error.message}
 const items=(list,trashed)=>list.map(r=>`<article class="saved-item"><div><h3>${esc(r.calculationName)}</h3><p>${esc(r.projectName||'No project')} · ${esc(r.snapshot.moduleTitle)} · v${esc(r.snapshot.appVersion)}</p><p>Saved ${esc(new Date(r.updatedAt).toLocaleString())}</p></div><div class="actions">${trashed?`<button class="button" data-record-action="restore" data-record-id="${esc(r.id)}">Restore</button>`:`<button class="button" data-record-action="load" data-record-id="${esc(r.id)}">Load</button><button class="button" data-record-action="pdf" data-record-id="${esc(r.id)}">Saved PDF</button><button class="button" data-record-action="rename" data-record-id="${esc(r.id)}">Rename</button><button class="button" data-record-action="trash" data-record-id="${esc(r.id)}">Move to trash</button>`}</div></article>`).join('');
 const activeRecords=records.filter(r=>!r.trashedAt),trashRecords=records.filter(r=>r.trashedAt),projects=projectNames(activeRecords);
 const groups=projects.map((project,index)=>{const list=activeRecords.filter(r=>projectKey(r.projectName)===projectKey(project));return `<details class="saved-project" data-project-index="${index}"><summary>${esc(project)} (${list.length})</summary><div class="actions project-actions"><button class="button" data-clear-project="${index}">Clear project (${list.length})</button></div>${items(list,false)}</details>`}).join('');
 document.querySelector('#main').innerHTML=`<div class="page-header"><h1 tabindex="-1" id="saved-heading">Saved calculations</h1><button class="button" id="clear-all-calculations" ${!activeRecords.length||failure?'disabled':''}>Clear all (${activeRecords.length})</button></div><p class="scope-note">Stored only in this browser on this device. Clearing site data removes saved calculations and trash. Export PDF reports for a separate copy. Loading a calculation recalculates it using the current engine; a Saved PDF preserves its original snapshot.</p><p id="action-status" class="action-status" role="status">${esc(failure)}</p><section aria-label="Saved calculations">${failure?'<p>Saved calculations could not be loaded. Your stored data has not been replaced.</p>':groups||'<p>No saved calculations yet. Open a calculator and save a valid result.</p>'}</section><details class="saved-trash"><summary>Trash (${records.filter(r=>r.trashedAt).length})</summary>${items(trashRecords,true)||'<p>Trash is empty.</p>'}</details>${note()}`;
 document.querySelectorAll('[data-record-action]').forEach(button=>button.onclick=()=>{try{const store=createRecordStore(),record=store.load(button.dataset.recordId),action=button.dataset.recordAction;if(action==='load'){const m=modules.find(m=>m.id===record.snapshot.moduleId);if(!m)throw new Error('This calculator is not available in this version.');states[m.id]={...defaults(m),...(m.id==='conductor'?calc.migrateConductorState(record.snapshot.inputs):m.id==='protection'?migrateProtectionState(record.snapshot.inputs):m.id==='drop'?calc.migrateDropState(record.snapshot.inputs):structuredClone(record.snapshot.inputs))};calculationNames[m.id]={projectName:record.projectName,calculationName:record.calculationName};lastSelectedProject=record.projectName;save();loadedNotice={id:m.id,text:`Loaded ${record.calculationName}. Recalculated with v2.6.0 from saved v${record.snapshot.appVersion}. Verify all inputs and confirmations before use.`};location.hash=m.id;calculator(m.id);actionStatus(loadedNotice.text);return}if(action==='pdf'){downloadPDF({...record.snapshot,projectName:record.projectName,calculationName:record.calculationName});actionStatus('Saved-snapshot PDF download started. It preserves the original engine version and results.');return}if(action==='rename'){showRecordDialog({records:store.list({includeTrashed:true}),projectName:record.projectName,calculationName:record.calculationName,rename:true,onSave:names=>{const renamed=store.rename(record.id,names);lastSelectedProject=renamed.projectName;savedLibrary();actionStatus('Calculation renamed.');document.querySelector('#saved-heading')?.focus()}});return}else if(action==='trash')store.trash(record.id);else if(action==='restore')store.restore(record.id);savedLibrary();actionStatus(action==='trash'?'Moved to trash. You can restore this calculation below.':action==='restore'?'Calculation restored.':'Calculation renamed.')}catch(error){actionStatus(error.message)}});
 const clear=(projectName)=>{const selected=activeRecords.filter(r=>projectName===undefined||projectKey(r.projectName)===projectKey(projectName));if(!selected.length)return;confirmRecordClear({count:selected.length,projectName,onConfirm:()=>{createRecordStore().trashMany(selected.map(r=>r.id));savedLibrary();actionStatus(`Moved ${selected.length} calculations to trash. Restore them below whenever needed.`);document.querySelector('#saved-heading')?.focus()}})};
 document.querySelector('#clear-all-calculations').onclick=()=>clear();
 document.querySelectorAll('[data-clear-project]').forEach(button=>button.onclick=()=>clear(projects[Number(button.dataset.clearProject)]));
}

function route(){closeRecordDialog();const id=location.hash.slice(1)||'overview';if(id==='overview')overview();else if(id==='saved')savedLibrary();else calculator(id);if(loadedNotice?.id===id){actionStatus(loadedNotice.text);loadedNotice=null}window.scrollTo(0,0)}
window.addEventListener('hashchange',route);route();
